function describeThreeAreas({ onDisk, staged, committed }) {
  const labels = [];
  if (staged !== committed) labels.push('changes to be committed');
  if (onDisk !== staged) labels.push('changes not staged for commit');
  if (labels.length === 0) labels.push('clean');
  return labels;
}

